/**
 * GMS (Generative Mission Synthesis) Common Types
 * Core type definitions used across all GMS modules
 */

import type { HermesParsedResponse, HermesResponse } from "@domain/agents/core/hermes-protocol.service.js";
import type { Mission } from "@shared/schema/missions/index.js";
import type { AgentContext } from "@domain/agents/core/types.js";

// ============================================================================
// Core GMS Types
// ============================================================================

/**
 * Blueprint candidate generated by synthesis engine
 */
export interface BlueprintCandidate {
  id: string;
  request: string;
  blueprint: MissionBlueprint;
  generation: GenerationMetadata;
  verifierScore?: VerifierScore;
  shadowResult?: ShadowResult;
  status: CandidateStatus;
  createdAt: Date;
}

export type CandidateStatus = 
  | "generated"     // Just created by synthesis
  | "scored"      // Has verifier score
  | "shadowing"   // Currently in shadow validation
  | "validated"   // Completed shadow runs
  | "deployed"    // Promoted to skill library
  | "rejected";   // Failed validation

/**
 * Mission blueprint structure (evolvable mission template)
 */
export interface MissionBlueprint {
  name: string;
  description: string;
  version: string;
  
  // Structure
  steps: MissionStepConfig[];
  agents: AgentConfig[];
  tools: ToolConfig[];
  
  // Data requirements
  inputSchema: Record<string, any>; // JSON Schema
  outputSchema: Record<string, any>;
  
  // Execution config
  maxDuration: number; // seconds
  retryPolicy: RetryPolicy;
  
  // Hermes-specific
  systemPrompt?: string;
  reasoningConfig: ReasoningConfig;
}

export interface MissionStepConfig {
  id: string;
  type: "agent" | "tool" | "decision" | "parallel" | "sequence";
  name: string;
  description: string;
  config: Record<string, any>;
  dependsOn?: string[];
  agentId?: string;
  toolName?: string;
  condition?: string; // For decision steps
}

export interface AgentConfig {
  id: string;
  name: string;
  model: string;
  temperature: number;
  maxTokens: number;
  systemPrompt?: string;
  allowedTools: string[];
  reasoningProtocol: "hermes_xml" | "json_manifest" | "cot";
  deliberationDepth: number; // How many thinking loops
}

export interface ToolConfig {
  name: string;
  version: string;
  required: boolean;
  timeout: number;
  retryCount: number;
}

export interface RetryPolicy {
  maxAttempts: number;
  backoffStrategy: "fixed" | "exponential" | "linear";
  backoffMs: number;
}

export interface ReasoningConfig {
  protocol: "hermes_xml";
  depth: number; // Recursive thinking depth
  selfReflect: boolean; // Include reflection step
  verifyActions: boolean; // Verify before each action
}

// ============================================================================
// Generation & Verifier Types
// ============================================================================

export interface GenerationMetadata {
  timestamp: Date;
  model: string;
  temperature: number;
  promptTokens: number;
  completionTokens: number;
  generationMethod: "llm_proposal" | "skill_composition" | "evolution";
  generation: number; // For tracking evolution rounds
  parentIds?: string[]; // For evolved candidates
  mutations?: MutationRecord[];
}

export interface MutationRecord {
  type: "prompt" | "tool" | "agent" | "structure" | "temperature";
  description: string;
  impact?: "positive" | "negative" | "neutral";
}

export interface VerifierScore {
  successProbability: number; // 0-1
  confidence: number; // Verifier's confidence in its prediction
  latencyEstimate: number; // Predicted execution time (ms)
  costEstimate: number; // Predicted cost ($)
  riskFactors: RiskFactor[];
  embedding?: number[]; // Vector representation of trace
}

export interface RiskFactor {
  type: "tool_failure" | "hallucination" | "timeout" | "cost_overrun" | "data_quality";
  severity: "low" | "medium" | "high" | "critical";
  description: string;
  mitigation?: string;
}

// ============================================================================
// Shadow Run Types
// ============================================================================

export interface ShadowRunConfig {
  candidateId: string;
  nVariations: number; // How many synthetic scenarios
  maxDuration: number; // Per variation timeout
  isolationLevel: "container" | "process" | "vm";
  recordHermesTraces: boolean;
  syntheticDataConfig: SyntheticDataConfig;
  
  // Scenarios to test
  scenarios?: ScenarioConfig[];
}

export interface SyntheticDataConfig {
  method: "schema_based" | "differential_privacy" | "llm_generated";
  preserveCardinality: boolean; // Keep same unique value counts
  addNoise: boolean;
  noiseScale?: number;
}

export interface ScenarioConfig {
  id: string;
  name: string;
  dataVariant: Record<string, any>; // Input variations
  expectedBehavior: "success" | "failure" | "edge_case";
  description: string;
}

export interface ShadowResult {
  candidateId: string;
  completedAt: Date;
  
  // Aggregate statistics
  successRate: number; // 0-1
  avgLatency: number; // ms
  minLatency: number;
  maxLatency: number;
  totalCost: number; // $
  
  // Individual run results
  runs: ShadowRunDetail[];
  
  // Hermes trace analysis
  hermesTraces: HermesTraceSummary[];
  
  // Failure analysis
  failureModes: FailureMode[];
  
  // Comparison to prediction
  predictionDelta: number; // |actual - predicted|
}

export interface ShadowRunDetail {
  variationId: string;
  scenarioId: string;
  success: boolean;
  latency: number;
  cost: number;
  error?: string;
  output?: any;
  traceId?: string; // Links to hermes_traces
}

export interface HermesTraceSummary {
  traceId: string;
  scenarioId: string;
  thoughtDepth: number; // Number of thinking steps
  toolCalls: number;
  toolFailures: number;
  selfReflections: number;
  keyDecisions: string[]; // Extracted decision points
}

export interface FailureMode {
  type: "tool_error" | "timeout" | "parsing_error" | "logic_error" | "hallucination";
  frequency: number; // How many runs
  scenarioIds: string[];
  description: string;
  rootCause?: string;
  fixable: boolean;
  suggestedFix?: string;
}

// ============================================================================
// Simulation Types
// ============================================================================

export interface SimulationResult {
  trace: SimulatedTrace;
  finalState: SimulatedState;
  duration: number;
  tokenEstimate: number;
}

export interface SimulatedTrace {
  steps: SimulatedStep[];
  thinkingBlocks: SimulatedThinking[];
  toolCalls: SimulatedToolCall[];
}

export interface SimulatedStep {
  type: "thinking" | "action" | "observation" | "error";
  content: string;
  estimatedLatency: number;
  estimatedTokens: number;
  confidence: number; // Simulation confidence
}

export interface SimulatedThinking {
  depth: number;
  content: string;
  estimatedTokens: number;
  topics: string[]; // Extracted reasoning topics
}

export interface SimulatedToolCall {
  tool: string;
  args: Record<string, any>;
  estimatedSuccess: number; // 0-1
  estimatedLatency: number;
  cached: boolean;
}

export interface SimulatedState {
  success: boolean;
  output: any;
  error?: string;
  intermediateResults: Record<string, any>;
}

// ============================================================================
// Skill & Evolution Types
// ============================================================================

export interface Skill {
  id: string;
  name: string;
  description: string;
  
  // The validated blueprint
  blueprint: MissionBlueprint;
  
  // Verification history
  verifierScore: VerifierScore;
  shadowResult: ShadowResult;
  productionStats: ProductionStats;
  
  // Evolution tracking
  generation: number;
  parentIds: string[];
  childrenIds: string[];
  mutations: MutationRecord[];
  evolutionLineage: string[]; // Full ancestry
  
  // Metadata
  tags: string[];
  createdAt: Date;
  lastUsedAt: Date;
  deprecatedAt?: Date;
  replacedBy?: string;
  
  // Usage
  usageCount: number;
  avgUserRating?: number;
}

export interface ProductionStats {
  totalRuns: number;
  successfulRuns: number;
  failedRuns: number;
  avgLatency: number;
  avgCost: number;
  lastRunAt?: Date;
  successRateTrend: "improving" | "stable" | "degrading";
}

export interface SkillComposition {
  id: string;
  name: string;
  description: string;
  
  // Composition graph
  rootSkillId: string;
  subSkills: ComposedSkill[];
  
  // Connections
  dataFlow: DataFlowEdge[];
  controlFlow: ControlFlowEdge[];
  
  // Validation
  composedVerifierScore: VerifierScore;
  composedShadowResult?: ShadowResult;
}

export interface ComposedSkill {
  skillId: string;
  role: string;
  inputMapping: Record<string, string>; // Maps parent input to skill input
  outputMapping: Record<string, string>;
}

export interface DataFlowEdge {
  from: { skillId: string; output: string };
  to: { skillId: string; input: string };
  transform?: string; // Optional transformation
}

export interface ControlFlowEdge {
  from: string; // skillId
  to: string; // skillId
  condition?: string; // Conditional flow
}

// ============================================================================
// API Types
// ============================================================================

export interface SynthesizeRequest {
  request: string;
  context?: {
    organizationId: number;
    userId: string;
    preferredModels?: string[];
    maxCost?: number;
    maxLatency?: number;
  };
  options?: {
    nCandidates?: number; // How many to generate
    /**
     * How many ranked candidates to return. Overrides the engine's configured
     * topK for this request only; omit to use the engine default.
     */
    topK?: number;
    includeShadowValidation?: boolean;
    autoDeploy?: boolean;
    useExistingSkills?: boolean;
  };
}

export interface SynthesizeResponse {
  requestId: string;
  candidates: BlueprintCandidate[];
  topRecommendation?: BlueprintCandidate;
  skillCompositions?: SkillComposition[];
  metadata: {
    generationTimeMs: number;
    modelUsed: string;
    tokensUsed: number;
  };
}

export interface ComposeRequest {
  goal: string;
  availableSkills: string[]; // Skill IDs to consider
  constraints?: {
    maxSkills?: number;
    maxDepth?: number;
    requiredOutput?: Record<string, any>;
  };
}

export interface HealthStatus {
  status: "healthy" | "needs_revalidation" | "degraded" | "deprecated";
  reason?: string;
  lastValidatedAt: Date;
  recommendation?: "none" | "revalidate" | "evolve" | "deprecate";
}

// ============================================================================
// Hermes Integration Types
// ============================================================================

export interface HermesInstrumentationConfig {
  enabled: boolean;
  captureThinking: boolean;
  captureToolCalls: boolean;
  captureResults: boolean;
  generateEmbeddings: boolean;
  
  // Filtering
  minThoughtLength?: number;
  excludePatterns?: string[];
  
  // Sampling
  sampleRate: number; // 0-1, for high-volume scenarios
  
  // Context enrichment
  includeMissionContext: boolean;
  includeAgentContext: boolean;
}

export interface EnrichedHermesTrace {
  // Standard Hermes parse
  parsed: HermesParsedResponse;
  
  // GMS enrichment
  traceId: string;
  missionContext?: {
    missionId?: number;
    jobId?: number;
    executionId?: number;
    stepIndex?: number;
  };
  agentContext?: AgentContext;
  
  // Timing
  startTime: Date;
  endTime: Date;
  latencyMs: number;
  
  // Token usage
  tokenUsage: {
    total: number;
    prompt: number;
    completion: number;
    costUsd?: number;
  };
  
  // Derived features for verifier
  features: HermesTraceFeatures;
}

export interface HermesTraceFeatures {
  thoughtDepth: number;
  toolDiversity: number; // Unique tools / total calls
  selfReflectionIndicators: string[]; // Phrases indicating reflection
  confidenceMarkers: number; // "probably", "maybe", etc.
  recursionDepth: number; // Nested thinking
  actionChaining: number; // Sequential dependent actions
}
